package android.widget;import android.content.res.ColorStateList;public class TextView extends android.view.View{public static boolean failWrite;public ColorStateList colors=ColorStateList.valueOf(101);public TextView(android.content.Context c){super(c);}public ColorStateList getTextColors(){return colors;}public void setTextColor(ColorStateList c){colors=c;if(failWrite)throw new IllegalStateException("text write");}public void setTextColor(int c){setTextColor(ColorStateList.valueOf(c));}}
